code.JavaScript:
const fs = require('fs');

function main() {
    const s = fs.readFileSync(0, 'utf-8').trim();
    if (s.length > 0) {
        const val = parseFloat(s);
        const expStr = val.toExponential(6);
        const [m, e] = expStr.split('e');
        const sign = e[0];
        const exp = e.slice(1).padStart(2, '0');
        console.log(m + 'e' + sign + exp);
    }
}

main();

